def _parse(inp):
    t = inp.split()
    n, m = int(t[0]), int(t[1])
    p = 2
    ops = []
    for _ in range(m):
        k = int(t[p])
        c = int(t[p + 1])
        p += 2
        a = [int(x) for x in t[p:p + k]]
        p += k
        ops.append((k, c, a))
    return n, m, ops, p, len(t)


def validate(inp):
