        n, m, ops, p, total = _parse(inp)
    except Exception:
        return False
    if not (2 <= n <= 2 * 10**5):
        return False
    if not (1 <= m <= 2 * 10**5):
        return False
    if p != total:
        return False
    sumk = 0
    for k, c, a in ops:
        sumk += k
        if not (2 <= k <= n):
            return False
        if len(a) != k:
            return False
        if not (1 <= c <= 10**9):
            return False
        for i in range(k):
            if not (1 <= a[i] <= n):
